{
  "measure_id": "MEAS-30633250",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Prohibits county jails from keeping individuals in custody past their scheduled release time solely because of a federal immigration detainer request."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C52",
      "effect": "costs",
      "direction": null,
      "quote": "No county jail may hold a person beyond the time the person would otherwise be released solely on the basis of a detainer request from federal immigration authorities.",
      "mechanism": "It prohibits local jails from participating in federal immigration enforcement by honoring detainer holds.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C53",
      "effect": "advances",
      "direction": null,
      "quote": "No county jail may hold a person beyond the time the person would otherwise be released solely on the basis of a detainer request from federal immigration authorities.",
      "mechanism": "It establishes a protection for immigrants against being detained by local authorities strictly for civil immigration enforcement purposes.",
      "certainty": "stated"
    },
    {
      "id": "f3",
      "clause_id": "§1",
      "concern_id": "C21",
      "effect": "moves",
      "direction": "shifts authority from local governments to the state",
      "quote": "No county jail may hold a person beyond the time the person would otherwise be released solely on the basis of a detainer request",
      "mechanism": "It removes the discretion of counties to decide whether to honor detainer requests, imposing a statewide prohibition.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Under current law, each county decides whether its jail will honor federal immigration detainer requests. This measure preempts that local control by banning all county jails from holding individuals past their normal release time solely for a federal immigration detainer.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Individuals subject to federal immigration detainers benefit by being released when their local charges are resolved. Local taxpayers may see marginal savings from not housing individuals for extra days. Federal immigration authorities bear the operational costs of locating and apprehending individuals in the community rather than taking custody of them at a local jail.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Counties that currently honor detainers will have to change their jail release protocols. Federal immigration authorities will likely adapt by increasing arrests in the community, at homes, or at courthouses, since they can no longer rely on county jails to hold individuals for them.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the issue of local jails detaining individuals for federal immigration enforcement without a criminal warrant. It resolves this by strictly prohibiting jails from holding individuals solely on the basis of an immigration detainer.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "The state asserts power over local jurisdictions by setting a uniform rule. County sheriffs lose the discretion to cooperate with federal detainers. Federal immigration enforcement loses a convenient mechanism for taking custody of individuals.",
      "disputed": false
    }
  ],
